<?php defined( 'ABSPATH' ) || exit;
$status_labels = array( 'ATTRIBUTE_ALREADY_SYNCED' => 'Já preenchido', 'ATTRIBUTE_CANDIDATE' => 'Novo valor encontrado', 'ATTRIBUTE_CONFLICT' => 'Conflito', 'ATTRIBUTE_MAPPING_REQUIRED' => 'Definir atributo de destino', 'ATTRIBUTE_REVIEW_REQUIRED' => 'Revisão necessária', 'ATTRIBUTE_NO_VALUE' => 'Sem valor', 'ATTRIBUTE_UNSUPPORTED_CONTEXT' => 'Contexto não suportado', 'ATTRIBUTE_SKIPPED' => 'Ignorado' );
$concept_labels = array( 'cor' => 'Cor', 'corrente_nominal' => 'Corrente nominal', 'potencia' => 'Potência', 'tensao' => 'Tensão', 'bitola' => 'Bitola', 'secao_nominal' => 'Seção nominal', 'numero_polos' => 'Número de polos', 'comprimento' => 'Comprimento', 'diametro' => 'Diâmetro', 'rosca' => 'Rosca', 'medida_nao_classificada' => 'Medida não classificada' );
$family_labels = array( 'electrical_breaker' => 'Disjuntores elétricos', 'electrical_wire_cable' => 'Fios e cabos elétricos', 'electrical_switchgear' => 'Dispositivos elétricos', 'hydraulic_pipe' => 'Tubos hidráulicos', 'hydraulic_fitting' => 'Conexões hidráulicas', 'pump' => 'Bombas', 'shower' => 'Chuveiros', 'tool' => 'Ferramentas', 'generic' => 'Genérica' );
$source_labels = array( 'WOO_EXISTING' => 'Atributo existente no WooCommerce', 'OLIST_STRUCTURED' => 'Campo estruturado do Olist', 'MANUAL_MAPPING' => 'Mapeamento manual', 'TITLE_PATTERN' => 'Padrão encontrado no título', 'DESCRIPTION_LABEL_VALUE' => 'Campo identificado na descrição' );
$confidence_labels = array( 'EXACT_STRUCTURED' => 'Exata / estruturada', 'HIGH_CONTEXTUAL' => 'Alta pelo contexto', 'MEDIUM_CONTEXTUAL' => 'Média pelo contexto', 'REVIEW_REQUIRED' => 'Requer revisão' );
$status_labels = array_merge( $status_labels, array( 'ATTRIBUTE_TERM_MATCHED' => 'Já existe no WooCommerce', 'ATTRIBUTE_TERM_MAPPING_REQUIRED' => 'Termo ou taxonomia requer mapeamento', 'ATTRIBUTE_UNIT_AMBIGUOUS' => 'Unidade ambígua', 'ATTRIBUTE_CONCEPT_AMBIGUOUS' => 'Conceito ambíguo', 'ATTRIBUTE_SOURCE_CONFLICT' => 'Conflito entre fontes', 'ATTRIBUTE_UNSUPPORTED_UNIT' => 'Unidade não suportada', 'ATTRIBUTE_DESTINATION_MISSING' => 'Taxonomia de destino ainda não criada' ) );
$concept_labels = array_merge( $concept_labels, array( 'secao_condutor' => 'Seção do condutor', 'potencia_aparente' => 'Potência aparente', 'fase' => 'Fase', 'espessura' => 'Espessura', 'largura_fita' => 'Largura da fita', 'dn_composto' => 'DN composto', 'medida_composta' => 'Medida composta' ) );
$source_labels['REJECTED_DISCOVERY'] = 'Descoberta rejeitada para bitola pelo contexto';
$confidence_labels = array_merge( $confidence_labels, array( 'HIGH_CONTEXT' => 'Alta pelo contexto', 'MEDIUM_CONTEXT' => 'Média pelo contexto', 'LOW_CONTEXT' => 'Baixa pelo contexto' ) );
$filter_label = static function ( string $key, string $value ) use ( $status_labels, $concept_labels, $source_labels, $confidence_labels, $family_labels ): string { $sets = array( 'status' => $status_labels, 'attribute_key' => $concept_labels, 'source' => $source_labels, 'confidence' => $confidence_labels, 'family' => $family_labels ); return $sets[ $key ][ $value ] ?? $value; };
?>
<div class="wrap">
	<h1>Atributos Persi</h1><div class="notice notice-info inline"><p><strong>Somente diagnóstico:</strong> nenhum atributo, taxonomia ou termo é criado ou alterado nesta versão.</p></div>
	<?php if ( $mapping_notice ) : ?><div class="notice notice-info inline"><p><?php echo esc_html( $mapping_notice ); ?></p></div><?php endif; ?>
	<h2>Atributos globais existentes no WooCommerce</h2>
	<table class="widefat striped"><thead><tr><th>Nome</th><th>Taxonomia</th><th>Termos</th><th>Produtos usando</th><th>Possível conceito</th></tr></thead><tbody><?php foreach ( $attributes as $attribute ) : ?><tr><td><?php echo esc_html( $attribute['name'] ); ?></td><td><code><?php echo esc_html( $attribute['taxonomy'] ); ?></code></td><td><?php echo esc_html( (string) $attribute['terms'] ); ?></td><td><?php echo esc_html( (string) $attribute['products'] ); ?></td><td><?php echo esc_html( $concept_labels[ $attribute['canonical'] ] ?? 'Revisão necessária' ); ?><?php if ( $attribute['duplicate'] ) : ?> <strong>— possível sobreposição</strong><?php endif; ?></td></tr><?php endforeach; ?><?php if ( ! $attributes ) : ?><tr><td colspan="5">Nenhum atributo global encontrado.</td></tr><?php endif; ?></tbody></table>

