		<tr><th><label for="family">Família opcional</label></th><td><select id="family" name="family"><option value="">Todas as famílias</option><?php foreach ( $family_labels as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>"><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></td></tr>
		<tr><th><label for="category_id">ID da categoria</label></th><td><input id="category_id" name="category_id" type="number" min="0" value="0"><p class="description">0 = todas as categorias.</p></td></tr>
		<tr><th><label for="attribute_key">Conceito canônico</label></th><td><select id="attribute_key" name="attribute_key" required><option value="">Selecione</option><?php foreach ( $concept_labels as $key => $label ) : if ( 'medida_nao_classificada' === $key ) { continue; } ?><option value="<?php echo esc_attr( $key ); ?>"><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></td></tr>
		<tr><th><label for="woo_taxonomy">Atributo destino</label></th><td><select id="woo_taxonomy" name="woo_taxonomy" required><option value="">Selecione</option><?php foreach ( $attributes as $attribute ) : ?><option value="<?php echo esc_attr( $attribute['taxonomy'] ); ?>"><?php echo esc_html( $attribute['name'] . ' — ' . $attribute['taxonomy'] ); ?></option><?php endforeach; ?></select></td></tr>
		<tr><th><label for="normalizer">Normalizador</label></th><td><select id="normalizer" name="normalizer"><option value="">Automático pelo conceito</option><option value="ampere">Ampere</option><option value="volt">Volt</option><option value="watt">Watt</option><option value="millimeter">Milímetro</option></select></td></tr>
	</tbody></table><?php submit_button( 'Salvar mapeamento para próximos diagnósticos' ); ?></form>
	<table class="widefat striped"><thead><tr><th>Origem</th><th>Família</th><th>Categoria</th><th>Conceito</th><th>Destino</th><th>Escrita automática</th></tr></thead><tbody><?php foreach ( $mappings as $mapping ) : ?><tr><td><?php echo esc_html( $mapping->origin_key ); ?></td><td><?php echo esc_html( $family_labels[ $mapping->family ?? '' ] ?? 'Todas' ); ?></td><td><?php echo esc_html( $mapping->category_id ? (string) $mapping->category_id : 'Todas' ); ?></td><td><?php echo esc_html( $concept_labels[ $mapping->attribute_key ] ?? $mapping->attribute_key ); ?></td><td><code><?php echo esc_html( $mapping->woo_taxonomy ); ?></code></td><td>DESATIVADA</td></tr><?php endforeach; ?><?php if ( ! $mappings ) : ?><tr><td colspan="6">Nenhum mapeamento manual aprovado.</td></tr><?php endif; ?></tbody></table>

	<h2>Diagnóstico de atributos <?php echo $run_id ? '#'.esc_html( (string) $run_id ) : ''; ?></h2>
	<?php if ( $summary ) : ?><p><strong>Produtos analisados:</strong> <?php echo esc_html( (string) $summary['products'] ); ?></p><div class="persi-attribute-summary"><?php foreach ( $summary['statuses'] as $item ) : ?><span><strong><?php echo esc_html( $status_labels[ $item->status ] ?? $item->status ); ?>:</strong> <?php echo esc_html( (string) $item->total ); ?></span><?php endforeach; ?></div>
	<h3>Candidatos por conceito</h3><div class="persi-attribute-summary"><?php foreach ( $summary['concepts'] as $item ) : ?><span><?php echo esc_html( $concept_labels[ $item->attribute_key ] ?? $item->attribute_key ); ?>: <?php echo esc_html( (string) $item->total ); ?></span><?php endforeach; ?></div>
	<h3>Ocorrências por regra</h3><div class="persi-attribute-summary"><?php foreach ( $summary['rules'] as $item ) : ?><span><?php echo esc_html( ( $source_labels[ $item->source ] ?? $item->source ) . ' / ' . ( $item->rule_id ?: 'sem regra' ) ); ?>: <?php echo esc_html( (string) $item->total ); ?></span><?php endforeach; ?></div><?php endif; ?>

	<form method="get" class="persi-attribute-filters"><input type="hidden" name="page" value="persi-catalog-attributes"><input type="hidden" name="run_id" value="<?php echo esc_attr( (string) $run_id ); ?>"><?php foreach ( array( 'status' => 'Situação', 'attribute_key' => 'Conceito', 'source' => 'Origem', 'confidence' => 'Confiança', 'family' => 'Família' ) as $key => $label ) : ?><label><?php echo esc_html( $label ); ?><select name="<?php echo esc_attr( $key ); ?>"><option value="">Todos</option><?php foreach ( $filter_values[ $key ] ?? array() as $value ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( $filters[ $key ], $value ); ?>><?php echo esc_html( $filter_label( $key, $value ) ); ?></option><?php endforeach; ?></select></label><?php endforeach; ?><label><input type="checkbox" name="show_synced" value="1" <?php checked( isset( $_GET['show_synced'] ) ); ?>> Mostrar já preenchidos</label><label><input type="checkbox" name="show_rejected" value="1" <?php checked( isset( $_GET['show_rejected'] ) ); ?>> Mostrar candidatos rejeitados</label><?php submit_button( 'Filtrar', 'secondary', '', false ); ?></form>

	<table class="widefat striped"><thead><tr><th>Produto / SKU</th><th>Categoria / família</th><th>Conceito</th><th>Original → normalizado / unidade</th><th>Origem / confiança</th><th>Destino / termo Woo</th><th>Situação</th><th>Detalhes</th></tr></thead><tbody><?php foreach ( $candidates as $candidate ) : ?><tr><td><?php echo esc_html( $candidate->product_name ?: '#'.$candidate->product_id ); ?><br><code><?php echo esc_html( $candidate->sku ?: 'sem SKU' ); ?></code></td><td><?php echo esc_html( $candidate->category_path ?: 'Sem categoria' ); ?><br><small><?php echo esc_html( $family_labels[ $candidate->family ] ?? $candidate->family ); ?></small></td><td><?php echo esc_html( $concept_labels[ $candidate->attribute_key ] ?? $candidate->attribute_key ); ?></td><td><?php echo esc_html( $candidate->raw_value ); ?> → <strong><?php echo esc_html( $candidate->normalized_value ); ?></strong><br><small>Unidade: <?php echo esc_html( $candidate->unit ?: '—' ); ?></small></td><td><?php echo esc_html( $source_labels[ $candidate->source ] ?? $candidate->source ); ?><br><small><?php echo esc_html( $confidence_labels[ $candidate->confidence ] ?? $candidate->confidence ); ?></small></td><td><code><?php echo esc_html( $candidate->woo_taxonomy ?: 'Não mapeado' ); ?></code><br><small><?php echo esc_html( $candidate->existing_term ?: 'Termo não encontrado' ); ?></small></td><td><?php echo esc_html( $status_labels[ $candidate->status ] ?? $candidate->status ); ?><br><small><code><?php echo esc_html( $candidate->status ); ?></code></small></td><td><details><summary>Ver evidência</summary><p><strong>Fonte/campo:</strong> <?php echo esc_html( $candidate->source . ' / ' . ( $candidate->source_field ?: '—' ) ); ?><br><strong>Trecho:</strong> <?php echo esc_html( $candidate->evidence ?: '—' ); ?><br><strong>Match:</strong> <?php echo esc_html( $candidate->raw_value ); ?><br><strong>Normalização:</strong> <?php echo esc_html( $candidate->normalized_value ); ?><br><strong>Regra:</strong> <code><?php echo esc_html( $candidate->rule_id ?: '—' ); ?></code><br><strong>Versão:</strong> <?php echo esc_html( $candidate->ruleset_version ?: '—' ); ?></p></details></td></tr><?php endforeach; ?><?php if ( ! $candidates ) : ?><tr><td colspan="8">Nenhum candidato corresponde aos filtros. Execute uma Simulação com o módulo Atributos.</td></tr><?php endif; ?></tbody></table>
